CREATE TABLE countries(id BIGSERIAL PRIMARY KEY, iso_code VARCHAR(2) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, currency_code VARCHAR(3), languages VARCHAR(255));
CREATE TABLE cities(id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, country_id BIGINT NOT NULL REFERENCES countries(id), description VARCHAR(1000), estimated_daily_budget NUMERIC(12,2) NOT NULL, tags VARCHAR(500), latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, CONSTRAINT uk_city_country UNIQUE(name,country_id));
CREATE TABLE trip_requests(id UUID PRIMARY KEY, departure_city VARCHAR(150) NOT NULL, nationality VARCHAR(100) NOT NULL, adults INTEGER NOT NULL CHECK(adults>=1), children INTEGER NOT NULL CHECK(children>=0), budget NUMERIC(14,2) NOT NULL CHECK(budget>0), currency VARCHAR(3) NOT NULL, duration_days INTEGER NOT NULL CHECK(duration_days BETWEEN 1 AND 90), travel_period VARCHAR(80), travel_style VARCHAR(80), destination_scope VARCHAR(80), interests VARCHAR(1000), preferred_destination VARCHAR(150), created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE trip_recommendations(id BIGSERIAL PRIMARY KEY, trip_id UUID NOT NULL REFERENCES trip_requests(id) ON DELETE CASCADE, city_id BIGINT NOT NULL REFERENCES cities(id), score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100), estimated_trip_budget NUMERIC(14,2) NOT NULL, budget_status VARCHAR(30) NOT NULL, explanation VARCHAR(1000), generated_at TIMESTAMPTZ NOT NULL, CONSTRAINT uk_trip_city UNIQUE(trip_id,city_id));
